CREATE DATABASE IF NOT EXISTS order_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE order_db;
CREATE TABLE orders (id BINARY(16) NOT NULL, order_number VARCHAR(40) NOT NULL, customer_id BINARY(16) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, status ENUM('CREATED','INVENTORY_RESERVED','PAID','PROCESSING','SHIPPED','DELIVERED','FAILED','CANCELLED') NOT NULL, currency CHAR(3) NOT NULL, subtotal DECIMAL(19,4) NOT NULL, discount_total DECIMAL(19,4) NOT NULL DEFAULT 0, shipping_total DECIMAL(19,4) NOT NULL DEFAULT 0, tax_total DECIMAL(19,4) NOT NULL DEFAULT 0, grand_total DECIMAL(19,4) NOT NULL, shipping_address JSON NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_order_number(order_number), UNIQUE KEY uk_order_customer_idempotency(customer_id,idempotency_key), KEY ix_order_customer_created(customer_id,created_at), KEY ix_order_status_created(status,created_at), CONSTRAINT ck_order_totals CHECK(subtotal >= 0 AND grand_total >= 0)) ENGINE=InnoDB;
CREATE TABLE order_items (id BINARY(16) NOT NULL, order_id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, variant_id BINARY(16) NOT NULL, sku VARCHAR(100) NOT NULL, product_name VARCHAR(300) NOT NULL, attributes JSON NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(19,4) NOT NULL, line_total DECIMAL(19,4) NOT NULL, PRIMARY KEY(id), KEY ix_order_item_order(order_id), CONSTRAINT ck_order_item_quantity CHECK(quantity > 0), CONSTRAINT fk_order_item_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE saga_steps (id BINARY(16) NOT NULL, order_id BINARY(16) NOT NULL, step_name ENUM('INVENTORY','PAYMENT','ORDER_CONFIRMATION') NOT NULL, state ENUM('PENDING','SUCCEEDED','FAILED','COMPENSATING','COMPENSATED') NOT NULL, correlation_id BINARY(16) NOT NULL, payload JSON, updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_saga_order_step(order_id,step_name), UNIQUE KEY uk_saga_correlation(correlation_id), CONSTRAINT fk_saga_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE outbox_event (id BINARY(16) NOT NULL, aggregate_type VARCHAR(80) NOT NULL, aggregate_id BINARY(16) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSON NOT NULL, occurred_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at TIMESTAMP(6), attempts INT NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_outbox_unpublished(published_at,occurred_at)) ENGINE=InnoDB;
